import type { RehypePlugin } from '@astrojs/markdown-remark'

import { fileURLToPath } from 'node:url'

import type { HastNode } from './wrap-elements'

import { wrapElements } from './wrap-elements'
import { readIcon } from './read-icon'
import { getText } from './get-text'

/**
 * Only the repository release notes receive the release composition.
 */
const CHANGELOG_PATH = fileURLToPath(
  new URL('../../changelog.md', import.meta.url),
)

/**
 * Commit references generated by changelogen, separate from issue links.
 */
const COMMIT_PATTERN = /\/commit\/[\da-f]+(?:$|[#?])/iu

/**
 * Categories with a distinct presentation; other headings remain intact.
 */
let categories = new Map([
  ['Performance Improvements', 'performance'],
  ['Breaking Changes', 'breaking'],
  ['Contributors', 'contributors'],
  ['Initial Release', 'initial'],
  ['Features', 'features'],
  ['Bug Fixes', 'fixes'],
])

let icons = new Map(
  [
    ['features', 'rocket'],
    ['fixes', 'bug'],
    ['performance', 'car'],
    ['breaking', 'alert-triangle'],
    ['initial', 'flame'],
  ].map(([kind, name]) => [kind!, readIcon(name!)]),
)

/**
 * Composes releases from their existing Markdown sections. Runs before heading
 * collection and search so their order matches the visible page.
 *
 * @returns Transformer scoped to the root changelog.
 */
export let rehypeChangelog: RehypePlugin = () => (tree, file) => {
  if (file.path !== CHANGELOG_PATH) {
    return
  }
  wrapElements(
    tree,
    node => node.tagName === 'section' && Boolean(getHeading(node, 'h2')),
    composeRelease,
  )
}

/**
 * Adds a release header, derived counts and categories without hiding notes.
 *
 * @param release - Section headed by a version.
 * @returns The same section with its presentation structure.
 */
function composeRelease(release: HastNode): HastNode {
  let children = release.children ?? []
  let title = getHeading(release, 'h2')!
  let sections = children.filter(node => node.tagName === 'section')
  let breaking = sections.find(node => getKind(node) === 'breaking')
  let breakingKeys = new Set(
    getItems(breaking)
      .map(getChangeKey)
      .filter(key => key !== undefined),
  )
  for (let section of sections) {
    let kind = getKind(section)
    if (kind === 'features' || kind === 'fixes' || kind === 'performance') {
      for (let list of getLists(section)) {
        list.children = list.children?.filter(
          item =>
            item.tagName !== 'li' ||
            !breakingKeys.has(getChangeKey(item) ?? ''),
        )
      }
    } else if (kind === 'breaking') {
      for (let item of getItems(section)) {
        removeBreakingLabel(item)
      }
    }
    setClass(
      section,
      'release-category',
      ...(kind ? [`release-${kind}`] : []),
      ...(kind === 'breaking' ? ['callout'] : []),
    )
    for (let list of getLists(section)) {
      setClass(list, 'release-changes')
    }
    let heading = getHeading(section, 'h3')
    let icon = icons.get(kind ?? '')
    if (heading && icon) {
      let copy = structuredClone(icon)
      /* SVG formatting whitespace must not become part of the heading title. */
      copy.children = copy.children?.filter(child => child.type === 'element')
      copy.properties = {
        ...copy.properties,
        className: ['release-icon'],
        ariaHidden: 'true',
      }
      heading.children = [copy, ...(heading.children ?? [])]
    }
  }
  let [firstCategory] = sections
  if (breaking && firstCategory && breaking !== firstCategory) {
    children.splice(children.indexOf(breaking), 1)
    children.splice(children.indexOf(firstCategory), 0, breaking)
  }
  let compare = children.find(
    node =>
      node.tagName === 'p' &&
      node.children?.some(child => getHref(child).includes('/compare/')),
  )
  if (compare) {
    setClass(compare, 'release-compare')
    let link = compare.children?.find(node => node.tagName === 'a')
    if (link) {
      link.children = [{ value: 'Compare changes', type: 'text' }]
    }
  }
  let counts = [
    ['features', 'feature', 'features'],
    ['fixes', 'fix', 'fixes'],
    ['performance', 'performance improvement', 'performance improvements'],
    ['breaking', 'breaking change', 'breaking changes'],
  ].flatMap(([kind, singular, plural]) => {
    let count = sections
      .filter(section => getKind(section) === kind)
      .reduce((total, section) => total + getItems(section).length, 0)
    return count ?
        [
          element('li', `release-count release-count-${kind}`, [
            {
              value: `${count} ${count === 1 ? singular : plural}`,
              type: 'text',
            },
          ]),
        ]
      : []
  })
  let header = element('header', 'release-header', [
    title,
    ...(compare ? [compare] : []),
    ...(counts.length > 0 ? [element('ul', 'release-summary', counts)] : []),
  ])
  release.children = [
    header,
    ...children.filter(node => node !== title && node !== compare),
  ]
  setClass(release, 'release')
  markCommits(release)
  return release
}

/**
 * Makes commit hashes visually separate metadata without changing destinations.
 *
 * @param node - Tree to decorate.
 */
function markCommits(node: HastNode): void {
  let children = node.children ?? []
  for (let [index, child] of children.entries()) {
    let href = getHref(child)
    if (child.tagName === 'a' && COMMIT_PATTERN.test(href)) {
      setClass(child, 'release-commit')
      let hash = getText(child)
      child.properties!['ariaLabel'] = `View commit ${hash}`
      if (/^[\da-f]{7,40}$/iu.test(hash.trim())) {
        child.children = [
          {
            children: [{ type: 'text', value: hash }],
            type: 'element',
            tagName: 'code',
          },
        ]
      }
      let before = children[index - 1]
      let after = children[index + 1]
      if (
        before?.type === 'text' &&
        /\(\s*$/u.test(before.value ?? '') &&
        after?.type === 'text' &&
        /^\s*\)/u.test(after.value ?? '')
      ) {
        before.value = before.value?.replace(/\(\s*$/u, '')
        after.value = after.value?.replace(/^\s*\)/u, '')
      }
    } else {
      markCommits(child)
    }
  }
}

/**
 * Requires matching text and commit URLs before removing a repeated change.
 *
 * @param item - Change list item.
 * @returns Stable comparison key, or no key for changes without commits.
 */
function getChangeKey(item: HastNode): undefined | string {
  let commits: string[] = []
  function collect(node: HastNode): void {
    let href = getHref(node)
    if (node.tagName === 'a' && COMMIT_PATTERN.test(href)) {
      commits.push(href)
    }
    if (!node.children) {
      return
    }
    for (let child of node.children) {
      collect(child)
    }
  }
  collect(item)
  if (commits.length === 0) {
    return undefined
  }
  let text = getText(item)
    .trim()
    .replace(/^Breaking change:\s*/u, '')
    .replaceAll(/\s+/gu, ' ')
  return `${commits.toSorted().join('|')}|${text}`
}

/**
 * Removes the redundant label where the section already says Breaking Changes.
 *
 * @param item - Change inside the breaking section.
 */
function removeBreakingLabel(item: HastNode): void {
  let first = item.children?.find(
    node => node.type !== 'text' || node.value?.trim(),
  )
  if (first?.type === 'text') {
    first.value = first.value?.replace(/^Breaking change:\s*/u, '')
  } else if (first?.tagName === 'p') {
    removeBreakingLabel(first)
  }
}

/**
 * Creates a small presentation wrapper around existing content.
 *
 * @param tagName - HTML element name.
 * @param className - Space-separated class names.
 * @param children - Existing or generated children.
 * @returns HTML tree element.
 */
function element(
  tagName: string,
  className: string,
  children: HastNode[],
): HastNode {
  return {
    properties: { className: className.split(' ') },
    type: 'element',
    children,
    tagName,
  }
}

/**
 * Reads direct lists, excluding nested explanations within a change.
 *
 * @param section - Category section.
 * @returns Direct ordered and unordered lists.
 */
function getLists(section: undefined | HastNode): HastNode[] {
  return (
    section?.children?.filter(
      node => node.tagName === 'ul' || node.tagName === 'ol',
    ) ?? []
  )
}

/**
 * Counts changes rather than their nested lists or paragraphs.
 *
 * @param section - Category section.
 * @returns Top-level changes.
 */
function getItems(section: undefined | HastNode): HastNode[] {
  return getLists(section).flatMap(
    list => list.children?.filter(node => node.tagName === 'li') ?? [],
  )
}

/**
 * Recognizes known category names after the emoji cleanup.
 *
 * @param section - Category section.
 * @returns Presentation kind for the category.
 */
function getKind(section: HastNode): undefined | string {
  let heading = getHeading(section, 'h3')
  return heading ? categories.get(getText(heading).trim()) : undefined
}

/**
 * Finds a direct heading, without accidentally selecting a nested category.
 *
 * @param node - Section to inspect.
 * @param tag - Heading level.
 * @returns Direct heading if present.
 */
function getHeading(node: HastNode, tag: string): undefined | HastNode {
  return node.children?.find(child => child.tagName === tag)
}

/**
 * Reads a link destination without coercing other property values.
 *
 * @param node - Link element.
 * @returns Destination, or an empty string for other elements.
 */
function getHref(node: HastNode): string {
  let href = node.properties?.['href']
  return typeof href === 'string' ? href : ''
}

/**
 * Sets presentation classes while retaining other element properties.
 *
 * @param node - Element to decorate.
 * @param names - Class names for the element.
 */
function setClass(node: HastNode, ...names: string[]): void {
  node.properties = { ...node.properties, className: names }
}
